$ErrorActionPreference = 'Stop'
$required = @('MIDSCENE_MODEL_BASE_URL','MIDSCENE_MODEL_API_KEY','MIDSCENE_MODEL_NAME','MIDSCENE_MODEL_FAMILY')
foreach ($name in $required) {
  if (-not [Environment]::GetEnvironmentVariable($name)) { throw "Missing environment variable: $name" }
}
npm install --save-dev @midscene/web playwright @playwright/test
$env:CHROMIUM_EXECUTABLE_PATH = $env:CHROMIUM_EXECUTABLE_PATH ?? 'C:\path\to\chromium.exe'
npx tsx src/poc01/run.ts

export type ActionType =
  | 'CLICK' | 'FILL' | 'CLEAR' | 'KEY' | 'SCROLL' | 'HOVER' | 'LOCATE' | 'WAIT';

export type ActionStatus = 'PENDING' | 'READY' | 'EXECUTING' | 'OBSERVED' | 'PASSED' | 'FAILED' | 'AMBIGUOUS';

export interface PlannedAction {
  stepId: string;
  action: ActionType;
  target: string;
  valueRef?: string;
  summary?: string;
}

export interface FullActionPlan {
  planId: string;
  caseId: string;
  goal: string;
  steps: PlannedAction[];
  expectedResultRef: string;
}

export interface ActionWindow {
  windowId: string;
  planId: string;
  previous: null | { stepId: string; summary: string; result: ActionStatus };
  current: PlannedAction;
  next: null | { stepId: string; summary: string };
  actionBudget: 1;
  cursor: number;
}

export interface LocatorCandidate {
  type: 'TEST_ID' | 'ROLE' | 'LABEL' | 'PLACEHOLDER' | 'TEXT' | 'CSS' | 'XPATH';
  value: string;
  unique: boolean;
  score: number;
}

export interface StepTrace {
  stepId: string;
  requested: PlannedAction;
  url: string;
  title: string;
  beforeScreenshot?: string;
  afterScreenshot?: string;
  element: {
    tagName: string;
    role: string | null;
    accessibleName: string | null;
    testId: string | null;
    visibleText: string | null;
    inputType: string | null;
    valueBefore: string | null;
    valueAfter: string | null;
  };
  locatorCandidates: LocatorCandidate[];
  waitCondition: Record<string, unknown> | null;
  network: Array<{ method: string; url: string; status?: number; requestBody?: unknown; responseBody?: unknown }>;
  stateAfter: { visibleTexts: string[]; businessState?: string };
  warnings: string[];
}

export interface PocResult {
  id: string;
  name: string;
  status: 'PASS' | 'PARTIAL' | 'BLOCKED' | 'FAIL';
  checks: Record<string, 'PASS' | 'FAIL' | 'BLOCKED'>;
  metrics?: Record<string, number | string>;
  notes: string[];
  artifacts: string[];
}

import test from 'node:test';import assert from 'node:assert/strict';import {ScheduleRegistry} from '../src/poc05/scheduler.js';
test('six-field weekly cron with timezone',()=>{const r=new ScheduleRegistry();r.create({scheduleId:'S',scriptArtifactId:'A',cron:'0 0 9 * * 3',timezone:'Asia/Shanghai',enabled:true,concurrencyPolicy:'FORBID_OVERLAP'});assert.equal(r.next('S',new Date('2026-07-13T00:00:00Z')).toISOString(),'2026-07-15T01:00:00.000Z');});
test('overlap is rejected',()=>{const r=new ScheduleRegistry();r.create({scheduleId:'S',scriptArtifactId:'A',cron:'0 0 9 * * 3',timezone:'Asia/Shanghai',enabled:true,concurrencyPolicy:'FORBID_OVERLAP'});r.begin('S');assert.throws(()=>r.begin('S'),/OVERLAP_FORBIDDEN/);r.end('S');});

